<script lang="ts">
 import MailNav from '$lib/components/newsletter/MailNav.svelte';
 let {data}=$props();
 // svelte-ignore state_referenced_locally
 const initial=data.settings;
 let name=$state(initial?.from_name??'山人-yamado-'),email=$state(initial?.from_email??''),reply=$state(initial?.reply_to??'info@yamado.co.jp'),organization=$state(initial?.organization??'株式会社山人'),address=$state(initial?.postal_address??''),enabled=$state(initial?.enabled??false),busy=$state(false),message=$state('');
 async function save(e:SubmitEvent){e.preventDefault();busy=true;message='';try{const f=new FormData();f.set('facility',data.facility);f.set('action','settings');f.set('data',JSON.stringify({from_name:name,from_email:email,reply_to:reply,organization,postal_address:address,enabled}));const r=await fetch('/admin/mail/api',{method:'POST',body:f}),j=await r.json();if(!r.ok)throw Error(j.error);message='配信設定を保存しました。';}catch(e){message=String(e);}finally{busy=false;}}
</script>
<svelte:head><title>配信設定 ｜ メルマガ</title></svelte:head><MailNav active="settings"/>
<h1 class="mb-6 text-2xl font-semibold">配信設定</h1><div class="grid gap-6 lg:grid-cols-2"><form onsubmit={save} class="panel"><h2>差出人・フッター</h2><label>差出人名<input required maxlength="100" bind:value={name}/></label><label>差出人メールアドレス<input required type="email" bind:value={email}/></label><label>返信先<input required type="email" bind:value={reply}/></label><label>会社・組織名<input required maxlength="200" bind:value={organization}/></label><label>郵便番号・住所<textarea required maxlength="500" rows="3" bind:value={address}></textarea></label><label class="flex items-start gap-3"><input type="checkbox" bind:checked={enabled}/>この施設の配信を有効にする</label><p class="text-sm text-stone-500">ResendのAPIキー、ドメイン認証、Webhookの接続が完了してから有効にしてください。認証されていない差出人はResend側で拒否されます。</p><button disabled={busy}>{busy?'保存中…':'設定を保存'}</button>{#if message}<p role="status">{message}</p>{/if}</form><section class="panel"><h2>Resend Transactional Pro</h2><p>コンタクトと配信停止はBookで管理し、Resendの送信APIを使います。</p><ol class="list-inside list-decimal space-y-3 text-sm"><li>Resendに送信ドメインを追加し、表示されたDNSレコードを設定</li><li>送信ドメインの認証完了を確認</li><li>APIキーとWebhook署名シークレットをサーバーに登録</li><li>差出人・住所を保存し、自分宛のテストメールで確認</li></ol><p class="text-sm text-stone-500">APIキーはこの画面に入力しません。配信停止リンクはすべての本配信に自動で付きます。</p><a class="underline" href="https://resend.com/domains" target="_blank" rel="noreferrer">Resendのドメイン設定を開く ↗</a></section></div>
<style>.panel{background:white;border:1px solid #e7e5e4;border-radius:12px;padding:24px;display:flex;flex-direction:column;gap:20px}.panel h2{font-size:18px;font-weight:600}label{font-size:14px}input:not([type=checkbox]),textarea{display:block;width:100%;margin-top:6px;border:1px solid #d6d3d1;border-radius:7px;padding:10px;font-size:14px}button{min-height:44px;border-radius:8px;background:#292524;color:white;padding:10px 16px}button:disabled{opacity:.5}</style>
